const t=(x,y,s,size=24,color='--ink',anchor='start')=>`<text x="${x}" y="${y}" font-size="${size}" fill="var(${color})" text-anchor="${anchor}">${s}</text>`;
const rect=(x,y,w,h,color='--surface',stroke='--line')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="15" fill="var(${color})" stroke="var(${stroke})" stroke-width="2"/>`;
const line=(d,color='--teal',dash=false)=>`<path d="${d}" fill="none" stroke="var(${color})" stroke-width="5" ${dash?'stroke-dasharray="7 7"':''} marker-end="url(#arrow-${color.slice(2)})"/>`;
export const svg=(body,label,w=1100,h=500)=>`<svg class="diagram" viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><defs>${['teal','amber','phase-three','muted'].map(c=>`<marker id="arrow-${c}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="var(--${c})"/></marker>`).join('')}</defs>${body}</svg>`;
export const credit=(text,url)=>`<figcaption class="credit">${url?`<a href="${url}" target="_blank" rel="noopener">${text}</a>`:text}</figcaption>`;
const nvidia='https://docs.nvidia.com/dgx/dgxgb200-user-guide/hardware.html';
const image=(name,alt)=>`<img src="../assets/references/${name}" alt="${alt}">`;
function rack(){return `<div class="hardware-pair"><figure class="hardware-photo">${image('lenovo-gb300-rack-front.jpg','Lenovo NVIDIA GB300 NVL72, front perspective of one complete rack.')}${credit('Lenovo · NVIDIA GB300 NVL72','https://lenovopress.lenovo.com/lp2357-lenovo-nvidia-gb300-nvl72-rack-scale-ai')}</figure><div class="hardware-notes"><div class="big-stat"><strong>72 <span>GPUs</span></strong><span>18 compute trays × 4 GPUs</span></div><div class="big-stat"><strong>36 <span>CPUs</span></strong><span>2 Grace CPUs per compute tray</span></div><div class="big-stat"><strong>9 <span>switch trays</span></strong><span>18 NVSwitch chips connect the GPUs</span></div></div></div>`;}
function tray(){return `<div class="tray-pair"><figure class="hardware-photo closed-tray">${image('nvidia-gb300-tray.png','Enclosed NVIDIA DGX GB300 compute tray.')}${credit('DGX GB300 compute tray',nvidia)}</figure><figure class="hardware-photo open-tray">${image('nvidia-gb300-tray-top.png','NVIDIA top view: two Grace CPUs, four Blackwell Ultra GPUs, ConnectX networking, storage and fans, with manufacturer labels.')}${credit('NVIDIA · Components beneath the cover',nvidia)}</figure></div>`;}
function superchip(){return `<div class="hardware-pair superchip"><figure class="hardware-photo">${image('nvidia-gb300-superchip.webp','NVIDIA Grace Blackwell Ultra superchip board: one Grace CPU, two Blackwell Ultra GPUs and two ConnectX-8 SuperNICs.')}${credit('NVIDIA · Grace Blackwell Ultra superchip','https://developer.nvidia.com/blog/inside-nvidia-blackwell-ultra-the-chip-powering-the-ai-factory-era/')}</figure><div class="hardware-notes"><div class="fact-line"><strong>Grace CPU</strong><span>Operating system, data preparation, work submission</span></div><div class="fact-line"><strong>Blackwell Ultra GPUs</strong><span>Parallel kernels and matrix operations</span></div><div class="fact-line"><strong>ConnectX-8</strong><span>Network traffic to the rest of the cluster</span></div></div></div>`;}
function dataPath(state,compact){
 const active=state.path, load=active==='load'?'--teal':'--line',local=active==='local'?'--teal':'--line',peer=active==='peer'?'--phase-three':'--line';
 const descriptions={load:'Host-staged load: storage → CPU memory → GPU HBM.',local:'The kernel reads GPU-local HBM through its memory controllers.',peer:'A partial result crosses NVLink and NVSwitch to another GPU.'};
 if(compact)return `<div class="path-mobile"><div class="path-object ${active==='load'?'active':''}"><b>Storage → network interface</b><span>Weights and input data</span></div><div class="path-object ${active==='load'?'active':''}"><b>Grace CPU + LPDDR5X</b><span>Preparation and work submission</span></div><div class="path-object ${active==='local'?'active':''}"><b>GPU HBM ⇄ GPU execution</b><span>Local operand reads</span></div><div class="path-object ${active==='peer'?'active':''}"><b>GPU → NVSwitch → peer GPU</b><span>Partial results</span></div><p class="path-description">${descriptions[active]}</p></div>`;
 const loadColor=active==='load'?'--teal':'--muted',localColor=active==='local'?'--teal':'--muted',peerColor=active==='peer'?'--phase-three':'--muted';
 let b=rect(20,265,180,105)+t(110,307,'Storage',24,'--ink','middle')+t(110,342,'Network interface',15,'--muted','middle');
 b+=rect(280,70,290,330)+t(425,107,'Host',18,'--muted','middle')+rect(320,145,210,80,'--surface-soft')+t(425,195,'Grace CPU',24,'--ink','middle')+rect(320,285,210,80)+t(425,319,'CPU memory',21,'--ink','middle')+t(425,345,'LPDDR5X',17,'--muted','middle');
 b+=rect(660,70,400,330)+t(860,107,'Accelerator',18,'--muted','middle')+rect(710,145,220,80,'--surface-soft')+t(820,195,'GPU execution',23,'--ink','middle')+rect(710,285,220,80)+t(820,335,'GPU HBM',24,'--ink','middle');
 b+=line('M200 325H320',loadColor)+line('M530 325H710',loadColor)+t(620,302,'NVLink-C2C',16,'--muted','middle')+line('M820 285V225',localColor);
 b+=line('M530 185H710','--muted',true)+t(620,163,'Launch kernel',16,'--muted','middle');
 b+=rect(685,435,375,60)+t(872,473,'NVSwitch → peer GPU',22,'--ink','middle')+line('M930 185H1015V435',peerColor);

 return `<div class="model-condition">${descriptions[active]}</div>${svg(b,descriptions[active])}`;
}
function switchedRack(compact){
 if(compact){let b=t(250,40,'One GB300 NVL72',22,'--muted','middle');[20,185,350].forEach((x,i)=>{b+=rect(x,90,130,90)+t(x+65,143,`GPU ${[1,2,72][i]}`,22,'--ink','middle');});b+=rect(20,285,460,130,'--surface-soft')+t(250,330,'NVLink switch plane',25,'--ink','middle')+t(250,366,'9 trays · 18 NVSwitch chips',20,'--muted','middle')+line('M85 180V285','--teal')+line('M250 180V285','--muted')+line('M415 285V180','--phase-three')+t(85,237,'Sends',18,'--teal','middle')+t(415,237,'Receives',18,'--phase-three','middle')+t(250,475,'Every GPU links to every switch chip.',21,'--ink','middle');return svg(b,'Selected GPUs communicate through the rack-wide NVSwitch plane.',500,530);}
 let b=t(550,38,'One GB300 NVL72',22,'--muted','middle');
 const xs=[70,450,830];
 xs.forEach((x,i)=>{b+=rect(x,105,200,100,'--surface')+t(x+100,164,`GPU ${[1,2,72][i]}`,27,'--ink','middle');});
 b+=rect(70,300,960,105,'--surface-soft')+t(550,346,'NVLink switch plane',26,'--ink','middle')+t(550,382,'9 switch trays · 18 NVSwitch chips',20,'--muted','middle');
 b+=line('M170 205V300','--teal')+line('M550 205V300','--muted')+line('M930 300V205','--phase-three');
 b+=t(280,258,'GPU 1 sends',19,'--teal')+t(790,258,'GPU 72 receives',19,'--phase-three');
 b+=t(550,465,'Each GPU has one NVLink connection to every switch chip.',20,'--ink','middle');
 return svg(b,'GPU 1 communicates with GPU 72 through a shared NVSwitch plane. The three drawn endpoints stand for GPUs in the 72-GPU rack.');
}
function interfaces(){return `<div class="hardware-pair"><figure class="hardware-photo">${image('nvidia-dgx-gb300-rear.png','NVIDIA rear assembly with separate NVLink cartridge, power bus and coolant manifolds.')}${credit('NVIDIA · DGX GB300 rear assembly',nvidia)}</figure><div class="hardware-notes"><div class="fact-line"><strong>Power busbar</strong><span>DC electrical supply</span></div><div class="fact-line"><strong>Coolant manifolds</strong><span>Liquid to and from cold plates</span></div><div class="fact-line"><strong>NVLink cartridge</strong><span>Copper signal links between GPUs and switches</span></div></div></div>`;}
export function hardwareVisual(id,state,compact){return ({rack,tray,superchip,'data-path':()=>dataPath(state,compact),'switched-rack':()=>switchedRack(compact),'rack-interfaces':interfaces}[id]||(()=>null))();}
export {t,rect,line};
